describe('Search Filter by Category - Category: search_filter', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should filter search results by category using checkboxes - happy path', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*').as('searchResults');

    // Perform initial search
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();

    // Wait for search results to load
    cy.wait('@searchResults');

    // Verify initial results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Click on the 'Electronics' category checkbox
    cy.get('[data-testid="category-checkbox-electronics"]').click();

    // Wait for filter to apply
    cy.wait('@searchResults');

    // Verify Electronics category is now filtered
    cy.get('[data-testid="result-item"]').should('have.class', 'electronics-filtered');

    // Verify other categories are not displayed
    cy.get('[data-testid="result-item"]').should('not.have.class', 'books-filtered');
    cy.get('[data-testid="result-item"]').should('not.have.class', 'clothing-filtered');

    // Verify search results count is updated
    cy.get('[data-testid="search-results-count"]').should('contain', '3 results');
  });

  it('should handle multiple category filters - edge case', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*').as('searchResults');

    // Perform initial search
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();

    // Wait for search results to load
    cy.wait('@searchResults');

    // Verify initial results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Click on 'Electronics' category checkbox
    cy.get('[data-testid="category-checkbox-electronics"]').click();

    // Wait for filter to apply
    cy.wait('@searchResults');

    // Click on 'Books' category checkbox
    cy.get('[data-testid="category-checkbox-books"]').click();

    // Wait for filter to apply
    cy.wait('@searchResults');

    // Verify both categories are now filtered
    cy.get('[data-testid="result-item"]').should('have.class', 'electronics-filtered');
    cy.get('[data-testid="result-item"]').should('have.class', 'books-filtered');

    // Verify search results count is updated
    cy.get('[data-testid="search-results-count"]').should('contain', '2 results');

    // Verify no results are displayed for unselected categories
    cy.get('[data-testid="result-item"]').should('not.have.class', 'clothing-filtered');

    // Verify filter UI updates to show selected categories
    cy.get('[data-testid="filter-panel"]').should('be.visible');
    cy.get('[data-testid="filter-panel"]').should('contain', 'Electronics');
    cy.get('[data-testid="filter-panel"]').should('contain', 'Books');

    // Verify filter panel is still responsive
    cy.get('[data-testid="filter-panel"]').click();
    cy.get('[data-testid="filter-panel"]').should('be.visible');
  });
});
